$ErrorActionPreference='SilentlyContinue'
"=== GPU PCIE raw ==="
nvidia-smi -q | Select-String -Pattern "Link Width|Link Gen|GPU Link" -Context 0,1 | Out-String -Width 200
"=== PCI locations ==="
$targets = Get-PnpDevice | Where-Object { $_.FriendlyName -match 'NVM Express|NVIDIA GeForce|PCI Express Root Complex|PCI Express.*Bridge' -and $_.Status -eq 'OK' }
foreach ($d in $targets) {
  $props = Get-PnpDeviceProperty -InstanceId $d.InstanceId -KeyName DEVPKEY_Device_LocationInfo,DEVPKEY_Device_Parent
  "{0} | {1} | parent={2}" -f $d.FriendlyName, ($props | Where-Object KeyName -eq 'DEVPKEY_Device_LocationInfo').Data, ($props | Where-Object KeyName -eq 'DEVPKEY_Device_Parent').Data
}
"=== load test: width while inference runs ==="
$job = Start-Job { curl.exe -s -m 60 http://localhost:11434/api/generate -d '{\"model\":\"qwen3.8:27b\",\"prompt\":\"Write a long detailed story about a dragon.\",\"stream\":false,\"keep_alive\":600}' | Out-Null }
Start-Sleep -Seconds 6
1..6 | ForEach-Object { nvidia-smi --query-gpu=pcie.link.gen.current,pcie.link.width.current,power.draw,utilization.gpu --format=csv,noheader; Start-Sleep -Seconds 4 }
"=== load job done: $($job.State) ==="

$ErrorActionPreference='SilentlyContinue'
"=== fire load ==="
cmd /c "start /b cmd /c curl.exe -s -m 90 http://localhost:11434/api/generate -d \"{\"\"model\"\":\"\"qwen3.8:27b\"\",\"\"prompt\"\":\"\"Write a very long detailed story about a dragon slayer.\"\",\"\"stream\"\":false,\"\"keep_alive\"\":600}\" > nul 2>&1"
Start-Sleep -Seconds 5
"=== link samples during load (gen,width,power,util) ==="
1..8 | ForEach-Object { nvidia-smi --query-gpu=pcie.link.gen.current,pcie.link.width.current,power.draw,utilization.gpu --format=csv,noheader; Start-Sleep -Seconds 4 }
"=== device locations ==="
foreach ($n in @('NVM Express Controller','NVIDIA GeForce','Standard NVM')) {
  Get-PnpDevice | Where-Object { $_.FriendlyName -like "*$n*" } | ForEach-Object {
    $lp=(Get-PnpDeviceProperty -InstanceId $_.InstanceId -KeyName DEVPKEY_Device_LocationPaths).Data
    "{0} => {1}" -f $_.FriendlyName, ($lp -join ' ;; ')
  }
}

$ErrorActionPreference='SilentlyContinue'
"=== PCI devices (GPU + NVMe controllers) ==="
Get-PnpDevice -PresentOnly | Where-Object { $_.InstanceId -match '^PCI\\VEN_(10DE|C0A9|15B7|8086)&' -and $_.Class -in @('Display','SCSIAdapter') } | ForEach-Object {
  $loc = (Get-ItemProperty -Path ("HKLM:\SYSTEM\CurrentControlSet\Enum\" + $_.InstanceId) -Name LocationInformation).LocationInformation
  "{0} [{1}] {2}" -f $_.FriendlyName, $_.Class, $loc
  "    {0}" -f $_.InstanceId
}
"=== root ports ==="
Get-CimInstance Win32_PnPEntity -Filter "Name like '%PCI Express Root Port%' or Name like '%PCI Express Root Complex%'" | ForEach-Object {
  $loc = (Get-ItemProperty -Path ("HKLM:\SYSTEM\CurrentControlSet\Enum\" + $_.DeviceID) -Name LocationInformation).LocationInformation
  "{0} => {1}" -f $_.Name, $loc
}

